INSERT INTO batch_collection_log (
    job_execution_id, job_name, data_type, region_code, `year_month`,
    house_type, deal_type, collected_count, skipped_count, failed_count,
    status, started_at, ended_at
) VALUES (
    #{jobExecutionId}, #{jobName}, #{dataType}, #{regionCode}, #{yearMonth},
    #{houseType}, #{dealType}, #{collectedCount}, #{skippedCount}, #{failedCount},
    #{status}, #{startedAt}, #{endedAt}
)
